  'profit-margin-calculator': { title: 'Profit Margin Calculator – Margin and Markup', description: 'Calculate profit, gross margin, markup or selling price from cost and revenue. Estimates exclude taxes and overhead.', faq: [{ question: 'What is the difference between margin and markup?', answer: 'Profit margin is profit divided by the selling price. Markup is profit divided by cost, so the percentages are different.' }, { question: 'Does this include tax or operating costs?', answer: 'No. Enter your own cost and selling price; the estimate does not include tax, shipping, fees or overhead.' }] },
