  'spreadsheet-converter': { title: 'XLSX to CSV Converter – Convert Spreadsheet Sheets', description: 'Choose a worksheet in an XLSX workbook and export its values to CSV, or preview and download CSV data locally.', faq: [{ question: 'Can I convert an Excel XLSX file to CSV?', answer: 'Yes. Choose a worksheet, preview its cell values and download that sheet as CSV.' }, { question: 'Does CSV keep formulas, formatting and multiple sheets?', answer: 'No. CSV is plain text for one table. Formatting, formulas, charts and other sheets are not preserved; formulas are never run.' }] },
  'subtitle-converter': { title: 'SRT to VTT Converter – Convert Subtitle Files', description: 'Convert subtitle files between SRT and WebVTT, shift cue timing and preview captions in your browser.', faq: [{ question: 'Can I convert SRT subtitles to VTT?', answer: 'Yes. Open an SRT file, choose WebVTT output and download the converted subtitle file. You can also convert VTT to SRT.' }, { question: 'Can I shift all subtitle timestamps?', answer: 'Yes. Enter a positive or negative time offset to move all cue times. Check the first and last captions after conversion.' }] },
