  'image-metadata-remover': { title: 'Remove EXIF Data – Image Metadata Remover', description: 'Create a fresh image copy without embedded EXIF or GPS metadata. Re-encoding may change image quality or size.', faq: [{ question: 'Can a photo contain GPS location data?', answer: 'Some image files include camera details and GPS coordinates. This tool re-encodes a supported image to create an output without its original metadata.' }, { question: 'Does metadata removal change the image?', answer: 'The visible image is re-encoded locally, so file size or quality can change. Keep the original if you need its embedded camera information.' }] },
  'gif-maker': { title: 'GIF Maker – Create a GIF from Images or Video', description: 'Create an animated GIF from 2–12 images or one video clip up to 8 seconds. Processing stays in your browser; format support varies.', faq: [{ question: 'Can I make a GIF from photos?', answer: 'Yes. Select 2–12 still images in order, set the frame delay and create a GIF locally.' }, { question: 'Can this tool convert a video to GIF?', answer: 'Yes. Select one video clip up to 8 seconds. Decoding depends on your browser; GIF uses a limited palette and may look less detailed than the source.' }] },
